recipes.code:
{
  "inputs": [
    {
      "id": "hermoso-token",
      "type": "promptString",
      "description": "Hermoso agent key (hmk_…) from app.hermoso.ai → Settings → Agents & API. Required against the hosted app.",
      "password": true
    }
  ],
  "servers": {
    "hermoso": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "hermoso@0.1.25",
        "mcp"
      ],
      "env": {
        "HERMOSO_TOKEN": "${input:hermoso-token}",
        "HERMOSO_API_BASE": "<hermoso-api-base>"
      }
    }
  }
}
